				continue
			}
			t.Errorf("no leak reported at line %d; reported lines: %v", want, lines)
		}
	}
}

// TestEmbeddedFixturesLeakNothing is the guard of criterion 1: every committed
// fixture, byte for byte as it sits in the tree, passes the leak check.
func TestEmbeddedFixturesLeakNothing(t *testing.T) {
	all, err := nexusfixture.All()
	if err != nil {
		t.Fatal(err)
	}
	files, err := filepath.Glob(filepath.Join("fixtures", "*", "*.http"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 || len(files) != len(all) {
		t.Fatalf("%d fixture files on disk, %d embedded: the scan would not cover what the tests replay", len(files), len(all))
	}

	exact := externalDenylist(t)
	for _, file := range files {
		data, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		name := strings.TrimSuffix(filepath.Base(file), ".http")
		for _, l := range nexusfixture.CheckLeaks(name, data, exact) {
			t.Errorf("%s line %d: leak, rule %q", file, l.Line, l.Rule)
		}
	}

	// The same files, as parsed and written back, say the same: Format is what
	// the recorder writes.
	for _, f := range all {
		for _, l := range nexusfixture.CheckLeaks(f.Name, nexusfixture.Format(f), exact) {
			t.Errorf("%s (formatted) line %d: leak, rule %q", f.Name, l.Line, l.Rule)
		}
	}
}


// TestRedactLeavesARealAnswerAsItIs: the recorder reads a bench answer, and an
// answer that was already clean must come out the same, byte for byte, in the
// file (that is what lets it write nothing for an unchanged answer). Stub
// fixtures cannot be turned back into a raw body and are left out.
func TestRedactLeavesARealAnswerAsItIs(t *testing.T) {
	all, err := nexusfixture.All()
	if err != nil {
		t.Fatal(err)
	}
	checked := 0
	for _, f := range all {
		for i, ex := range f.Exchanges {
			if ex.Stub != "" {
				continue
			}
			checked++
			raw := nexusfixture.RawExchange{
				Method: ex.Method, Target: ex.Target, Host: ex.Host,
				RequestHeader: ex.RequestHeader.Clone(), Status: ex.Status,
				Header: ex.Header.Clone(), Body: slices.Clone(ex.Body),
			}
			got := nexusfixture.Redact(raw)
			got.Reason, ex.Reason = "", "" // the raw answer has none: Format falls back to the standard phrase

			want, have := f, f
			want.Exchanges, have.Exchanges = []nexusfixture.Exchange{ex}, []nexusfixture.Exchange{got}
			if w, h := nexusfixture.Format(want), nexusfixture.Format(have); !bytes.Equal(w, h) {
				t.Errorf("%s exchange %d: Redact changed a clean answer\nwant:\n%s\ngot:\n%s", f.Name, i+1, w, h)
			}
