func TestFixturesMatchTheBenchVersion(t *testing.T) {
	bench, err := readBenchVersion(filepath.FromSlash(descriptorPath))
	if err != nil {
		t.Fatal(err)
	}
	fixtures, err := nexusfixture.All()
